     nr,nc=r+dx,c+dy
     if 0<=nr<R and 0<=nc<C and g[nr][nc]==8 and (nr,nc) not in acc:acc.add((nr,nc));q.append((nr,nc))
 while q:
  x,y=q.popleft()
  for dx,dy in nbg:
   nx,ny=x+dx,y+dy
